def parse_ranges(specs, total):
    if not specs:
        return [(1,total)] if total else []
    res=[]
    for s in specs:
        try:
            if '::' in s:
                a,c=s.split('::',1); center=int(a or '1'); ctx=int(c or '0'); start=center-ctx; end=center+ctx
            elif s.count(':')>=2:
                a,b,c=s.split(':',2); start=int(a or '1'); end=int(b) if b else total; ctx=int(c or '0'); start-=ctx; end+=ctx
            elif ':' in s:
                a,b=s.split(':',1)
                if a == '': start=1
                else: start=int(a)
                if b == '': end=total
                elif b.startswith('+'): end=start+int(b[1:] or '0')
                else: end=int(b)
                if start < 0 and a.startswith('-'):
                    start=total+start+1
            else:
                start=int(s); end=start
            if start < 1: start=1
            if end > total: end=total
            if end >= start and total:
                res.append((start,end))
        except Exception:
            pass
    return res

def split_lines(data):
    parts = data.splitlines(True)
    lines=[]
    for p in parts:
        if p.endswith(b'\r\n'):
            lines.append((p[:-2], True, b'\r\n'))
        elif p.endswith(b'\n'):
            lines.append((p[:-1], True, b'\n'))
        elif p.endswith(b'\r'):
            lines.append((p[:-1], True, b'\r'))
        else:
            lines.append((p, False, b''))
    return lines

