            if blank_count < limit:
                out.append(item)
            blank_count += 1
        else:
            blank_count = 0
            out.append(item)
    return out

def decode_bytes_surrogate(b):
    return b.decode('utf-8','surrogateescape')

def tab_placeholder(col, tabw):
    tw = tabw if tabw > 0 else 4
    n = tw - (col % tw)
    if n <= 1:
        return '↹', col+1
    return '├' + ('─' * (n-2)) + '┤', col+n

def show_all_text(content, hasnl, nl, opts):
    s = decode_bytes_surrogate(content)
    out=[]; col=0
    for ch in s:
        o = ord(ch)
        if ch == ' ':
            out.append('·'); col+=1
        elif ch == '\t':
            t,col = tab_placeholder(col, opts.tabs); out.append(t)
        elif 0xDC80 <= o <= 0xDCFF:
            out.append('\\x%02X' % (o-0xDC00)); col += 4
        elif o < 32 or o == 127:
            if opts.notation == 'caret':
                if o == 127: out.append('^?')
                else: out.append('^' + chr(o+64))
                col += 2
            else:
                out.append(chr(0x2400 + o) if o < 32 else '␡'); col += 1
        else:
            out.append(ch); col += 1
