    use_header = active and (('header-filename' in opts.style) or ('header-filesize' in opts.style) or use_grid)
    color = (opts.color == 'always' and os.environ.get('NO_COLOR') is None)
    # Fast/raw path: no display transformation.
    if not active and not opts.show_all and not opts.squeeze and not opts.ranges and not opts.diff:
        return data
    if not active and not opts.show_all:
        # plain transformed/ranged output preserving original newlines
        out=bytearray()
        for c,h,nl,no in selected:
            out += c
            if h: out += nl if nl else b'\n'
        return bytes(out)
    chunks=[]
    if active:
        if use_grid:
            chunks.append(rule_line('┬', opts, color))
        if use_header:
            disp = opts.file_name or (name if name is not None else 'stdin')
            empty = '   <EMPTY>' if len(data)==0 else ''
            if use_grid:
                prefix = '     │ '
                if color: prefix = '     \x1b[38;5;246m│ \x1b[0m'
            else:
                prefix = '     '
            fname = f"File: {disp}{empty}"
            if color: fname = "File: \x1b[1m" + disp + "\x1b[0m" + empty
            chunks.append(prefix + fname + '\n')
            if 'header-filesize' in opts.style:
                chunks.append(prefix + f"Size: {human_size(len(data))}\n")
            if use_grid:
                chunks.append(rule_line('┼', opts, color))
    maxno = max([no for *_,no in selected], default=0)
    gutter = max(4, len(str(maxno)))
    last_no=None
    for c,h,nl,no in selected:
        if active and 'snip' in opts.style and last_no is not None and no > last_no + 1 and opts.ranges:
            if use_grid:
                chunks.append(' ... │ ' + ('─ '*18) + '8< ' + ('─ '*18) + '\n')
            else:
                chunks.append(' ...' + '─ '*18 + '8< ' + '─ '*18 + '\n')
        last_no=no
        expand = active and not opts.show_all
        text = show_all_text(c,h,nl,opts) if opts.show_all else normal_text(c, opts, expand=expand)
        if use_numbers:
            num = f"{no:>{gutter}}"
            if color: num = f"\x1b[38;5;246m{num}\x1b[0m"
            sep = ' │ ' if use_grid else ' '
            if color and use_grid: sep = ' \x1b[38;5;246m│\x1b[0m '
            chunks.append(num + sep + text + '\n')
        elif use_grid:
            sep = '     │ '
            if color: sep = '     \x1b[38;5;246m│\x1b[0m '
            chunks.append(sep + text + ('\n' if active else (nl.decode('ascii','ignore') if h else '')))
        elif active:
            chunks.append(text + '\n')
        else:
            chunks.append(text + ('\n' if h else ''))
    if active and use_grid:
        chunks.append(rule_line('┴', opts, color))
    return ''.join(chunks).encode('utf-8','surrogateescape')

def read_source(path):
    if path == '-':
        return (sys.stdin.buffer.read(), None, None)
    try:
        st=os.stat(path)
        if stat.S_ISDIR(st.st_mode):
            return (None, path, 'isdir')
        with open(path,'rb') as f: return (f.read(), path, None)
    except FileNotFoundError:
        return (None, path, 'notfound')
    except IsADirectoryError:
        return (None, path, 'isdir')
    except PermissionError:
        return (None, path, 'perm')
    except OSError as e:
        return (None, path, ('os',e))

def file_error(path, kind):
    if kind == 'isdir': msg=f"'{path}' is a directory."
    elif kind == 'notfound': msg=f"'{path}': No such file or directory (os error 2)"
    elif kind == 'perm': msg=f"'{path}': Permission denied (os error 13)"
    elif isinstance(kind, tuple): msg=f"'{path}': {kind[1]}"
    else: msg=f"'{path}': error"
    return f"\x1b[31m[bat error]\x1b[0m: {msg}\n"

def run(opts):
    files = opts.files[:] if opts.files else ['-']
    active = should_decorate(opts)
    status=0
    for f in files:
        data, name, err = read_source(f)
        if err:
            err_text(file_error(name, err)); status=1; continue
        if opts.quiet_empty and len(data)==0 and not active:
            continue
        display_name = opts.file_name or (name if name else None)
        try:
            sys.stdout.buffer.write(process_source(data, display_name, opts, active))
        except BrokenPipeError:
            return 1
    return status

def diagnostic_text():
    # Mostly static, with the invoked command line adjusted.
    s = read_text('src/data/diagnostic.txt')
    if not s:
        return "#### Software version\n\n" + VERSION
    cmd = ' '.join(shlex.quote(x) for x in sys.argv)
    s = re.sub(r"```bash\n.*?--diagnostic .*?\n```", f"```bash\n{cmd} \n```", s, flags=re.S)
    return s

def main():
    try:
        parsed = parse_args(sys.argv[1:])
    except RuntimeError as e:
        err_text(str(e)); return 2
    kind = parsed[0]
    if kind == 'cache': return handle_cache(parsed[1])
    if kind == 'help_short': out_text(short_help()); return 0
    if kind == 'help_long': out_text(long_help()); return 0
    if kind == 'version': out_text(VERSION); return 0
    if kind == 'data':
        out_text(read_text('src/data/'+parsed[1])); return 0
    if kind == 'diagnostic': out_text(diagnostic_text()); return 0
    if kind == 'run': return run(parsed[1])
    return 0

if __name__ == '__main__':
    try:
        sys.exit(main())
    except BrokenPipeError:
        try: sys.stderr.close()
        except Exception: pass
        sys.exit(1)
